/**
 * Batch capability lookup backing the admin user-management panel's
 * per-row ownership/instructor badges — one call per visible page of
 * users instead of N per-user fetches. Admin-only.
 */
export const usersApiCapabilities = <ThrowOnError extends boolean = false>(options: Options<UsersApiCapabilitiesData, ThrowOnError>): RequestResult<UsersApiCapabilitiesResponses, UsersApiCapabilitiesErrors, ThrowOnError> => (options.client ?? client).get<UsersApiCapabilitiesResponses, UsersApiCapabilitiesErrors, ThrowOnError>({ url: '/users/user-capabilities', ...options });

/**
 * Fetches one platform account. Admin-only.
 */
export const usersApiGet = <ThrowOnError extends boolean = false>(options: Options<UsersApiGetData, ThrowOnError>): RequestResult<UsersApiGetResponses, UsersApiGetErrors, ThrowOnError> => (options.client ?? client).get<UsersApiGetResponses, UsersApiGetErrors, ThrowOnError>({ url: '/users/{id}', ...options });

/**
 * Re-activates a suspended account, clearing suspension bookkeeping. Admin-only.
 */
export const usersApiReactivate = <ThrowOnError extends boolean = false>(options: Options<UsersApiReactivateData, ThrowOnError>): RequestResult<UsersApiReactivateResponses, UsersApiReactivateErrors, ThrowOnError> => (options.client ?? client).post<UsersApiReactivateResponses, UsersApiReactivateErrors, ThrowOnError>({ url: '/users/{id}/reactivate', ...options });

/**
 * Suspends an account with a reason, blocking sign-in. Admin-only.
 */
export const usersApiSuspend = <ThrowOnError extends boolean = false>(options: Options<UsersApiSuspendData, ThrowOnError>): RequestResult<UsersApiSuspendResponses, UsersApiSuspendErrors, ThrowOnError> => (options.client ?? client).post<UsersApiSuspendResponses, UsersApiSuspendErrors, ThrowOnError>({
    url: '/users/{id}/suspend',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});
